{"sql":"-- Step 2: Create stored procedure generate_monthly_report
CREATE TABLE IF NOT EXISTS employees.monthly_reports (
  report_id SERIAL PRIMARY KEY,
  report_date DATE NOT NULL,
  department_count INTEGER NOT NULL,
  total_employees INTEGER NOT NULL,
  avg_salary DECIMAL NOT NULL,
  generated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now()
);

CREATE OR REPLACE PROCEDURE employees.generate_monthly_report(report_date DATE)
LANGUAGE plpgsql
AS $$
DECLARE
  dept_count INT;
  total_emp INT;
  avg_sal DECIMAL;
  new_report_id INT;
BEGIN
  SELECT COUNT(*) INTO dept_count FROM employees.departments;
  SELECT COUNT(*) INTO total_emp FROM employees.employees WHERE current_flag = true;
  SELECT AVG(s.amount) INTO avg_sal FROM employees.salaries s JOIN employees.employees e ON s.employee_id = e.employee_id WHERE e.current_flag = true AND s.to_date = '9999-01-01';

  INSERT INTO employees.monthly_reports(report_date, department_count, total_employees, avg_salary)
  VALUES (report_date, dept_count, total_emp, avg_sal)
  RETURNING report_id INTO new_report_id;

  RETURN new_report_id;
END;
$$;"}

{"sql":"-- Step 3: Create trigger and trigger function for high_salary_alert
CREATE TABLE IF NOT EXISTS employees.salary_alerts (
  alert_id SERIAL PRIMARY KEY,
  employee_id INT NOT NULL,
  salary_amount DECIMAL NOT NULL,
  alert_date TIMESTAMP WITHOUT TIME ZONE DEFAULT now(),
  status VARCHAR(20) DEFAULT 'new'
);

CREATE OR REPLACE FUNCTION employees.high_salary_alert()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.amount > 120000 THEN
    INSERT INTO employees.salary_alerts(employee_id, salary_amount, alert_date, status)
    VALUES (NEW.employee_id, NEW.amount, now(), 'new');
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_high_salary_alert ON employees.salaries;
CREATE TRIGGER trg_high_salary_alert
AFTER INSERT ON employees.salaries
FOR EACH ROW
EXECUTE FUNCTION employees.high_salary_alert();" }

