{"sql":"-- Step 2: Create monthly_reports table and stored procedure generate_monthly_report
DROP TABLE IF EXISTS employees.monthly_reports;
CREATE TABLE employees.monthly_reports (
  report_id SERIAL PRIMARY KEY,
  report_date DATE NOT NULL,
  department_count INTEGER NOT NULL,
  total_employees INTEGER NOT NULL,
  avg_salary DECIMAL NOT NULL,
  generated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now()
);

CREATE OR REPLACE FUNCTION employees.generate_monthly_report(report_date DATE)
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
  dept_count INT;
  total_emp INT;
  avg_sal DECIMAL;
  new_report_id INT;
BEGIN
  SELECT COUNT(*) INTO dept_count FROM employees.department;
  SELECT COUNT(DISTINCT de.employee_id) INTO total_emp FROM employees.department_employee de WHERE de.to_date = '9999-01-01';
  SELECT AVG(s.amount)::DECIMAL INTO avg_sal FROM employees.salary s WHERE s.to_date = '9999-01-01';

  INSERT INTO employees.monthly_reports(report_date, department_count, total_employees, avg_salary)
  VALUES (report_date, dept_count, total_emp, avg_sal)
  RETURNING report_id INTO new_report_id;

  RETURN new_report_id;
END;
$$;"}

